function rotateSiteImages(p){const pool=imagePlan(p.type,(p.id||p.name)+Date.now(),20),need=Math.max(1,(p.items||[]).length+4);const slots=pool.slice(0,need);p.banner=slots.shift()||p.banner||"";p.gallery=slots.splice(0,3);(p.items||[]).forEach((it,i)=>{it.img=slots[i]||""});return p}
function repairImageRepetition(p){const pool=imagePlan(p.type,p.id||p.name,20),used=new Set(),take=()=>{while(pool.length){const u=pool.shift();if(u&&!used.has(u)){used.add(u);return u}}return ""};if(!p.banner){const b=take();if(b)p.banner=b}else used.add(p.banner);if(!Array.isArray(p.gallery))p.gallery=[];p.gallery=p.gallery.map(g=>{if(!g)return"";if(used.has(g)){const n=take();return n||""}used.add(g);return g});while(p.gallery.length<3){const n=take();if(!n)break;p.gallery.push(n)}if(Array.isArray(p.items))p.items.forEach(i=>{if(!i)return;if(i.img&&used.has(i.img)){const n=take();i.img=n||""}else if(!i.img&&p.contentIsSuggested){const n=take();if(n)i.img=n}if(i.img)used.add(i.img)});return p}
