function autoVisualFor(p){const k=tplKey(p.type),imgs=IMAGE_BANK[k]||IMAGE_BANK.generic,map={restaurant:"heroFull",pizza:"heroFull",barber:"heroSplit",salon:"heroSplit",shop:"heroSplit",market:"heroFull",generic:"heroSplit"};return{visualStyle:p.visualStyle&&VISUAL_STYLES[p.visualStyle]?p.visualStyle:"auto",layoutVariant:p.layoutVariant&&LAYOUTS[p.layoutVariant]?p.layoutVariant:(map[k]||"heroSplit"),images:imgs}}
function fillContent(p){const T=TPL[tplKey(p.type)],pr=presetFor(p.type),v=variantFor(p);p.title=p.title||p.name;p.description=T.about(p.name);p.items=generateSuggestedItems(p.type,p.name);p.sections=sectionsForLevel(p.level||"professional");p.reviews=p.reviews||[];p.visualVariant=v.id;Object.assign(p,{c1:pr.c1,c2:pr.c2,font:v.font,dark:v.dark,visualStyle:"auto",layoutVariant:v.hero,density:v.density,btn:v.shape,contentIsSuggested:true});const imgs=imagePlan(p.type,p.name+String(p.id||""),20);p.banner=imgs.shift()||relevantImage(p.type,"hero",p.name);p.gallery=imgs.splice(0,8);p.items.forEach((it,i)=>{it.img=imgs[i]||""});seedBusinessData(p);p.designProposals=makeDesignProposals(p);p.selectedDesign=0;applyDesignProposal(p,0);repairImageRepetition(p);}
function norm(p){if(typeof p.items==="string")p.items=p.items.split(/\n+/).filter(Boolean).map(l=>{const[m,...r]=l.split(/\s[—-]\s/);return{cat:"",name:m.trim(),price:r.join(" ").replace(/^R\$\s*/,""),desc:"",img:""}});if(p.type==="hairdresser")p.type=/barb/i.test(p.name||"")?"barber":"salon";const txt=[p.name,p.category,p.description].filter(Boolean).join(" ");if(/pet shop|agro pet|petshop|produtos pet/i.test(txt))p.type="pet";const pr=presetFor(p.type||"other"),v=variantFor(p);const out=Object.assign({title:p.name,description:"",items:[],gallery:[],reviews:[],banner:"",btn:v.shape,level:p.level||"professional",sections:sectionsForLevel(p.level||"professional"),published:false,c1:p.color||pr.c1,c2:pr.c2,font:v.font,dark:v.dark,visualStyle:"auto",layoutVariant:v.hero,density:v.density,visualVariant:v.id,contentIsSuggested:false,modules:defaultModules(p.type),staff:[],services:[],plans:[],classes:[],rooms:[],specialties:[],designProposals:null,selectedDesign:0,designImages:[]},p);ensureBusinessData(out);ensureDesignProposals(out);applyDesignProposal(out,out.selectedDesign);return repairImageRepetition(out)}
platforms=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(OLD_KEY)||localStorage.getItem("radarPlatformsV10")||localStorage.getItem("radarPlatformsV9")||localStorage.getItem("radarPlatformsV8")||localStorage.getItem("radarPlatformsV7")||"[]").map(norm); try{const saved=JSON.parse(localStorage.getItem("radarProspectionLocationV14")||"null");if(saved&&saved.lat&&saved.lon)here=saved}catch{}
function save(){localStorage.setItem(KEY,JSON.stringify(platforms));renderPlatforms();renderServiceCentral()}
function createPlatform(b){const p=norm({id:crypto.randomUUID(),name:b.name,type:b.type,phone:b.phone,whatsapp:b.whatsapp,instagram:b.instagram,address:b.address,createdAt:new Date().toISOString(),level:"professional",visualStyle:"auto"});fillContent(p);platforms.push(p);save();openEditor(p,"adm")}
/* ---------- Renderização do site do cliente ---------- */
function money(v){v=String(v||"").trim();return v?(/^R\$/i.test(v)?v:"R$ "+v):""}
function siteCSS(p){const v=variantFor(p);const r={pill:"999px",round:"12px",square:"2px"}[p.btn||v.shape]||"999px";const dark=p.dark,accent=p.c1||"#d89b3d",second=p.c2||"#191919";const max=p.level==="complete"?1240:p.level==="professional"?1160:980;const gap=p.density==="compact"?12:18;const heroMin=v.id==="clean"?560:v.id==="bold"?700:650;const radius=v.id==="square"?2:v.id==="luxe"?24:14;return`*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:${dark?"#0b0b0d":"#f5f2ed"};color:${dark?"#f5f2ec":"#171717"}.site{--c1:${accent};--c2:${second};--surface:${dark?"#151518":"#fff"};--muted:${dark?"#b7b1a8":"#666"};font-family:${p.font},system-ui,sans-serif;line-height:1.55;min-height:100vh}.site *{box-sizing:border-box}.nav{position:sticky;top:0;z-index:10;background:${dark?"rgba(8,8,9,.86)":"rgba(255,255,255,.9)"};backdrop-filter:blur(14px);padding:15px clamp(18px,5vw,70px);display:flex;align-items:center;gap:22px;border-bottom:1px solid rgba(128,128,128,.18)}.nav a{color:${dark?"#fff":"#111"};text-decoration:none;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.05em}.nav .brand{margin-right:auto;font-size:19px;text-transform:none;letter-spacing:0}.nav .btn{color:#fff}.hero{min-height:${heroMin}px;display:flex;align-items:center;background-size:cover;background-position:center;color:#fff;position:relative}.hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.82),rgba(0,0,0,.38) 62%,rgba(0,0,0,.1))}.hero-content{position:relative;z-index:1;max-width:${max}px;width:100%;margin:auto;padding:80px clamp(20px,6vw,80px)}.hero.center{text-align:center;justify-content:center}.hero.center .hero-content{max-width:850px}.hero.editorial{align-items:flex-end}.hero h1{font-size:clamp(46px,7vw,92px);line-height:.94;letter-spacing:-.045em;margin:14px 0;max-width:900px}.hero p{font-size:clamp(15px,1.7vw,20px);max-width:680px;color:rgba(255,255,255,.85);margin:0 0 25px}.eyebrow{display:inline-block;text-transform:uppercase;letter-spacing:.18em;font-size:11px;color:${accent};font-weight:900}.hero-actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;background:${accent};color:#fff!important;padding:12px 20px;text-decoration:none;font-weight:900;border-radius:${r};margin:4px;border:1px solid transparent}.btn.o{background:transparent;border-color:rgba(255,255,255,.75)}.wrap{max-width:${max}px;margin:auto;padding:20px clamp(18px,4vw,45px) 80px}.site section{padding:65px 0}.site section.alt{background:${dark?"#111114":"#fff"};margin-left:-45px;margin-right:-45px;padding-left:45px;padding-right:45px}.site h2{font-size:clamp(30px,4vw,52px);line-height:1;letter-spacing:-.035em;margin:8px 0 25px}.kicker{font-size:11px;text-transform:uppercase;letter-spacing:.18em;font-weight:900;color:${accent}}.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:${gap}px}.it{display:flex;gap:14px;padding:0;border:1px solid rgba(128,128,128,.15);background:${dark?"#151518":"#fff"};border-radius:${radius}px;overflow:hidden;margin:0}.it img{width:150px;height:150px;object-fit:cover}.it div{padding:16px;flex:1}.it small{opacity:.72}.pr{font-weight:900;color:${accent};white-space:nowrap;padding:16px}.gal{display:grid;grid-template-columns:1.4fr .8fr .8fr;grid-auto-rows:220px;gap:10px}.gal img{width:100%;height:100%;object-fit:cover;border-radius:12px}.gal img:first-child{grid-row:span 2}.rv,.feature,.faq{padding:22px;border-radius:15px;background:${dark?"#151518":"#fff"};border:1px solid rgba(128,128,128,.14);margin:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.feature img{width:100%;aspect-ratio:1.1;object-fit:cover}.story{display:grid;grid-template-columns:1fr 1fr;gap:35px;align-items:center}.story img{width:100%;aspect-ratio:1.1;object-fit:cover;border-radius:16px}.promo{padding:35px;border-radius:18px;background:linear-gradient(110deg,${accent},${second});color:#fff;display:flex;align-items:center;justify-content:space-between;gap:20px}.promo h2{margin:0;color:#fff}.contact{display:grid;grid-template-columns:1fr 1fr;gap:25px;padding:35px;border-radius:18px;background:${second};color:#fff}.site footer{padding:45px clamp(20px,5vw,70px);background:${dark?"#050506":"#111"};color:#fff;display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:25px}.site footer h4{color:${accent};margin:0 0 8px}.site footer p,.site footer a{color:#aaa;font-size:12px}.wm{position:fixed;right:8px;bottom:8px;width:20px;height:20px;opacity:.25;pointer-events:none;border-radius:4px}.wordmark{font-weight:950;letter-spacing:-.045em;text-wrap:balance}.nav .wordmark{font-size:20px}.site a{text-underline-offset:3px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.story,.contact{grid-template-columns:1fr}.site section.alt{margin-left:-18px;margin-right:-18px;padding-left:18px;padding-right:18px}.site footer{grid-template-columns:1fr 1fr}}@media(max-width:620px){.nav a:not(.brand){display:none}.hero{min-height:590px}.hero h1{font-size:48px}.cards{grid-template-columns:1fr}.gal{grid-template-columns:1fr 1fr;grid-auto-rows:170px}.gal img:first-child{grid-row:span 1}.it{display:block}.it img{width:100%;height:180px}.contact,.site footer{grid-template-columns:1fr}.promo{display:block}}`}

function bookingSection(p){
 if(!moduleOn(p,"booking"))return "";
 const services=(p.services&&p.services.length?p.services:p.items||[]), staff=p.staff||[];
 return '<section id="agendamento" class="alt"><span class="kicker">Agendamento</span><h2>Escolha como você quer ser atendido.</h2><form class="booking-form" data-booking="1">'+
   '<select name="service" required><option value="">Escolha o serviço</option>'+services.map(function(x){return '<option>'+esc(x.name||"")+(x.price?' — '+esc(money(x.price)):"")+'</option>'}).join("")+'</select>'+
   '<select name="professional"><option value="">Qualquer profissional</option>'+staff.map(function(x){return '<option>'+esc(x.name||"")+'</option>'}).join("")+'</select>'+
   '<input name="date" type="date" required><select name="time" required><option value="">Horário preferido</option>'+["08:00","09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00","18:00"].map(function(x){return '<option>'+x+'</option>'}).join("")+'</select>'+
   '<button class="btn" type="submit">Solicitar agendamento</button></form><p class="micro">O pedido será enviado pelo WhatsApp. A confirmação final depende da disponibilidade real do estabelecimento.</p></section>';
}
function reservationSection(p){
 if(!moduleOn(p,"reservations"))return "";
 return '<section id="reserva"><div class="contact"><div><span class="kicker" style="color:#fff">Reservas</span><h2>Reserve sua mesa.</h2><p>Informe data, horário e quantidade de pessoas. A confirmação é feita pelo estabelecimento.</p></div>'+
   '<form class="booking-form" data-reservation="1"><input name="date" type="date" required><input name="time" type="time" required><input name="people" type="number" min="1" max="30" placeholder="Pessoas" required><button class="btn" type="submit">Solicitar reserva</button></form></div></section>';
}
function orderSection(p){
 if(!moduleOn(p,"orders")&&!moduleOn(p,"delivery"))return "";
 return '<section id="pedido"><div class="promo"><div><span class="kicker" style="color:#fff">Pedido</span><h2>Escolha um item e peça pelo WhatsApp.</h2><p>O Radar monta a mensagem automaticamente com o item escolhido.</p></div>'+
   (p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'" target="_blank">Abrir WhatsApp</a>':"")+'</div></section>';
}
function specializedSections(p){
 const k=p.type,out=[];
 if(["barber","salon","pet","car_repair"].includes(k))out.push(bookingSection(p));
 if(["restaurant","pizza"].includes(k))out.push(reservationSection(p));
 if(["restaurant","pizza","fast_food","cafe","bakery","shop","market","pet"].includes(k))out.push(orderSection(p));
 if(k==="gym"&&moduleOn(p,"plans"))out.push('<section id="planos"><span class="kicker">Planos</span><h2>Escolha seu plano.</h2><div class="cards">'+(p.plans||[]).map(function(x){return '<article class="feature"><h3>'+esc(x.name)+'</h3><strong class="pr">'+esc(money(x.price))+'</strong><p>'+esc(x.desc||"")+'</p>'+(p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'?text='+encodeURIComponent("Olá! Quero saber mais sobre o plano "+x.name+" da "+p.name+".")+'" target="_blank">Tenho interesse</a>':"")+'</article>'}).join("")+'</div></section>');
 if(k==="gym"&&moduleOn(p,"classes"))out.push('<section id="aulas" class="alt"><span class="kicker">Horários</span><h2>Aulas e modalidades</h2><div class="cards">'+(p.classes||[]).map(function(x){return '<article class="feature"><h3>'+esc(x.name)+'</h3><p>'+esc(x.days||"")+' '+esc(x.time||"")+'</p><small>'+esc(x.desc||"")+'</small></article>'}).join("")+'</div></section>');
 if(k==="clinic"&&moduleOn(p,"specialties"))out.push('<section id="especialidades"><span class="kicker">Atendimento</span><h2>Especialidades e serviços</h2><div class="cards">'+(p.specialties||[]).map(function(x){return '<article class="feature"><h3>'+esc(x.name)+'</h3><p>'+esc(x.desc||"")+'</p></article>'}).join("")+'</div></section>');
 if(k==="hotel"&&moduleOn(p,"rooms"))out.push('<section id="acomodacoes"><span class="kicker">Hospedagem</span><h2>Acomodações</h2><div class="cards">'+(p.rooms||[]).map(function(x){return '<article class="feature">'+(x.img?'<img src="'+esc(x.img)+'" alt="">':"")+'<h3>'+esc(x.name)+'</h3><strong class="pr">'+esc(money(x.price))+'</strong><p>'+esc(x.desc||"")+'</p></article>'}).join("")+'</div></section>');
 if(k==="car_repair"&&moduleOn(p,"quote"))out.push('<section id="orcamento" class="alt"><span class="kicker">Orçamento</span><h2>Conte o que seu veículo precisa.</h2><form class="booking-form" data-quote="1"><input name="vehicle" placeholder="Carro / moto / modelo" required><input name="service" placeholder="Serviço desejado" required><textarea name="details" placeholder="Descreva o problema"></textarea><button class="btn" type="submit">Pedir orçamento</button></form></section>');
 return out.join("");
}
function siteHTML(p){
 const T=TPL[tplKey(p.type)], enabled=new Set((p.sections||[]).filter(function(s){return s.on}).map(function(s){return s.k}));
 const primary=(p.designImages&&p.designImages.filter(Boolean).length?p.designImages:[]),imgs=(p.gallery&&p.gallery.filter(Boolean).length?p.gallery:RELEVANT_STOCK[tplKey(p.type)]||RELEVANT_STOCK.generic).filter(Boolean),visuals=(primary.length?primary:imgs);
 const layout=p.layoutVariant||"heroSplit", heroClass=layout==="heroCentered"?"center":layout==="editorial"?"editorial":"";
 const navKeys=["about","items","offers","gallery","team","reviews","faq","location","contact"].filter(function(k){return enabled.has(k)});
 const anchor=function(k){return k==="about"?"sobre":k==="items"?(T.kind.toLowerCase().includes("serv")?"servicos":"cardapio"):k};
 const extraNav=moduleOn(p,"booking")?'<a href="#agendamento">Agendar</a>':moduleOn(p,"reservations")?'<a href="#reserva">Reservar</a>':moduleOn(p,"orders")?'<a href="#pedido">Pedir</a>':"";
 const nav=p.level==="essential"?"":'<nav class="nav"><a class="brand wordmark" href="#top"><span>'+esc(p.name)+'</span></a>'+
   navKeys.slice(0,5).map(function(k){return '<a href="#'+anchor(k)+'">'+esc(SECTIONS[k])+'</a>'}).join("")+extraNav+
   (p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'" target="_blank">'+(["barber","salon","pet","car_repair"].includes(p.type)?"Agendar":"Pedir agora")+'</a>':"")+'</nav>';
 const cta=p.whatsapp?'<a class="btn" href="'+esc(wa(p.whatsapp))+'" target="_blank">'+(["barber","salon","pet","car_repair"].includes(p.type)?"Falar / agendar pelo WhatsApp":"Pedir pelo WhatsApp")+'</a>':"";
 const bg=(p.banner||visuals[0])?' style="background-image:url(\''+esc(p.banner||imgs[0])+'\')"':"";
 const suggested=p.contentIsSuggested?'<div class="draft-note">Conteúdo inicial sugerido pelo Radar. Confirme informações, preços, horários e disponibilidade antes de publicar.</div>':"";
 const hero='<header class="hero '+heroClass+'"'+bg+'><div class="hero-content">'+suggested+'<span class="eyebrow">'+esc(labels[p.type]||"Estabelecimento")+' · V14</span><h1>'+esc(p.title||p.name)+'</h1><p>'+esc(p.description||"")+'</p><div class="hero-actions">'+cta+(p.instagram?'<a class="btn o" href="'+esc(ig(p.instagram))+'" target="_blank">Instagram</a>':"")+'</div></div></header>';
 let body="";
 if(enabled.has("about")&&p.description)body+='<section id="sobre"><div class="story"><div><span class="kicker">Conheça</span><h2>Uma experiência feita para você.</h2><p>'+esc(p.description)+'</p>'+cta+'</div>'+(visuals[1]?'<img src="'+esc(visuals[1])+'" alt="">':"")+'</div></section>';
 if(enabled.has("items")&&p.items.length)body+='<section id="'+anchor("items")+'" class="alt"><span class="kicker">'+esc(T.kind)+'</span><h2>Veja nossas opções</h2><div class="menu-grid">'+p.items.slice(0,16).map(function(i){return '<article class="menu-item">'+(i.img?'<img src="'+esc(i.img)+'" alt="">':"")+'<div class="menu-body"><small>'+esc(i.cat||"Destaque")+'</small><h3>'+esc(i.name)+'</h3><p>'+esc(i.desc||"")+'</p><div class="item-bottom"><strong class="pr">'+esc(money(i.price))+'</strong>'+(moduleOn(p,"orders")&&p.whatsapp?'<button class="btn item-order" data-item="'+esc(i.name)+'">Pedir</button>':"")+'</div></div></article>'}).join("")+'</div></section>';
 if(enabled.has("offers"))body+='<section id="ofertas"><div class="promo"><div><span class="kicker" style="color:#fff">Oferta</span><h2>Destaques da semana</h2></div>'+cta+'</div></section>';
 if(moduleOn(p,"gallery")&&visuals.length)body+='<section id="galeria"><span class="kicker">Visual</span><h2>Galeria</h2><div class="gal">'+visuals.slice(0,6).map(function(x){return '<img src="'+esc(x)+'" alt="">' }).join("")+'</div></section>';
 if(moduleOn(p,"reviews")&&p.reviews.length)body+='<section id="avaliacoes"><span class="kicker">Confiança</span><h2>Avaliações</h2><div class="cards">'+p.reviews.slice(0,4).map(function(r){return '<div class="rv"><b style="color:var(--c1)">★★★★★</b><p>'+esc(r.text)+'</p><strong>— '+esc(r.name)+'</strong></div>'}).join("")+'</div></section>';
 if(enabled.has("faq"))body+='<section id="faq"><span class="kicker">Ajuda</span><h2>Perguntas frequentes</h2><div class="faq"><b>Como entrar em contato?</b><p>Use WhatsApp, telefone ou Instagram.</p></div><div class="faq"><b>Onde fica?</b><p>'+esc(p.address||"Consulte nosso contato.")+'</p></div></section>';
 if(moduleOn(p,"staff")&&p.staff.length)body+='<section id="equipe"><span class="kicker">Equipe</span><h2>Quem atende você</h2><div class="cards">'+p.staff.map(function(x){return '<article class="feature">'+(x.img?'<img src="'+esc(x.img)+'" alt="">':"")+'<h3>'+esc(x.name)+'</h3><p>'+esc(x.role||"")+'</p><small>'+esc(x.specialty||"")+'</small></article>'}).join("")+'</div></section>';
 if(enabled.has("location"))body+='<section id="localizacao"><div class="contact"><div><span class="kicker" style="color:#fff">Visite</span><h2>Estamos por aqui.</h2><p>'+esc(p.address||"Endereço não cadastrado")+'</p>'+(p.address?'<a class="btn" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.address)+'" target="_blank">Abrir no mapa</a>':"")+'</div><div><h3>Contato</h3><p>'+esc(p.phone||"")+'</p>'+cta+'</div></div></section>';
 if(enabled.has("contact"))body+='<section id="contato" class="alt"><div class="contact"><div><span class="kicker" style="color:#fff">Contato</span><h2>Vamos conversar?</h2><p>'+esc(p.address||"")+'</p></div><div>'+cta+(p.phone?'<a class="btn o" href="tel:'+esc(p.phone)+'">Ligar</a>':"")+'</div></div></section>';
 body+=specializedSections(p);
 const footer='<footer><div><h3>'+esc(p.name)+'</h3><p>'+esc(p.description||"")+'</p></div><div><h4>Contato</h4><p>'+esc(p.phone||"")+'</p><p>'+esc(p.address||"")+'</p></div><div><h4>Redes</h4>'+(p.instagram?'<p><a href="'+esc(ig(p.instagram))+'" target="_blank">Instagram</a></p>':"")+(p.whatsapp?'<p><a href="'+esc(wa(p.whatsapp))+'" target="_blank">WhatsApp</a></p>':"")+'</div><div><h4>Radar de Clientes</h4><p>Plataforma modular criada com o Radar de Clientes.</p></div></footer><img class="wm" src="'+esc(logoURL)+'" alt="">';
 return '<div class="site" id="top">'+nav+hero+'<main class="wrap">'+body+'</main>'+footer+'</div>';
}
const fullDoc=function(p){
 const name=String(p.name||"").replace(/[^\wÀ-ÿ ]/g,""), waNum=JSON.stringify(p.whatsapp||"");
 const script='<script>(function(){function go(msg){var n='+waNum+'.replace(/\\D/g,"");if(n.length===10||n.length===11)n="55"+n;if(!n){alert("WhatsApp do estabelecimento não está cadastrado.");return}location.href="https://wa.me/"+n+"?text="+encodeURIComponent(msg)}document.addEventListener("click",function(e){var b=e.target.closest("[data-item]");if(b)go("Olá! Gostaria de pedir: "+b.getAttribute("data-item")+". Negócio: '+name+'. ");});document.addEventListener("submit",function(e){var f=e.target;if(!f.matches("form"))return;e.preventDefault();var fd=new FormData(f),pairs=[];fd.forEach(function(v,k){if(v)pairs.push(k+": "+v)});go("Olá! Gostaria de solicitar atendimento para '+name+'.\\n"+pairs.join("\\n"));});})();<\\/script>';
 return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+esc(p.description||p.name)+'"><meta property="og:title" content="'+esc(p.title||p.name)+'"><meta property="og:description" content="'+esc(p.description||"")+'"><title>'+esc(p.title||p.name)+'</title><style>'+siteCSS(p)+'</style></head><body>'+siteHTML(p)+script+'</body></html>';
};

/* ---------- V14 Central de Serviços ---------- */
const SERVICE_MODULES={social:{icon:"📱",name:"Redes Sociais",desc:"Posts, stories, bio, calendário e ideias adaptadas ao negócio."},whatsapp:{icon:"💬",name:"WhatsApp Business",desc:"Perfil, catálogo, mensagens e menu de atendimento."},photos:{icon:"📸",name:"Fotos comerciais",desc:"Planejamento de fotos, formatos, banners e materiais comerciais."},catalog:{icon:"📋",name:"Catálogo / Cardápio",desc:"Produtos, serviços, categorias, preços e adicionais."},booking:{icon:"📅",name:"Agendamento / Reservas",desc:"Estrutura de horários e fluxo de solicitação conforme o negócio."},marketing:{icon:"📈",name:"Marketing e Prospecção",desc:"Oportunidades, mensagens e acompanhamento comercial."}};
const SERVICE_KEY="radarServiceProjectsV14";
function serviceProjects(){try{return JSON.parse(localStorage.getItem(SERVICE_KEY)||"[]")}catch{return[]}}
function saveServiceProject(x){const a=serviceProjects(),i=a.findIndex(y=>y.id===x.id);if(i<0)a.push(x);else a[i]=x;localStorage.setItem(SERVICE_KEY,JSON.stringify(a))}
function recommendedServices(p){if(!p)return[];const a=[];if(!p.whatsapp)a.push("whatsapp");if(!p.items?.length)a.push("catalog");if(!p.gallery?.length)a.push("photos");if(["barber","salon","pet","gym","clinic","hotel","car_repair"].includes(p.type))a.push("booking");a.push("marketing");return [...new Set(a)].slice(0,5)}
function renderServiceCentral(){const mount=$("serviceCentral");if(!mount)return;const current=platforms[0];const cards=Object.entries(SERVICE_MODULES).map(([k,v])=>`<article class="service-card"><div class="service-icon">${v.icon}</div><h3>${v.name}</h3><p>${v.desc}</p><button class="primary" data-service="${k}">Abrir serviço</button></article>`).join("");let rec="";if(current){rec=recommendedServices(current).map(k=>`<button data-service="${k}" class="recommend">${SERVICE_MODULES[k].icon} ${SERVICE_MODULES[k].name}</button>`).join("");rec=`<div class="recommended"><h3>🎯 Serviços recomendados para ${esc(current.name)}</h3><div class="recommend-list">${rec}</div></div>`}else rec='<div class="suggestion-note">Crie uma plataforma para receber recomendações específicas.</div>';mount.innerHTML=`<section class="panel service-central"><div class="section-head"><div><span class="eyebrow-ui">V14 · CENTRAL</span><h2>📦 Central de Serviços</h2><p>Ferramentas separadas que usam os mesmos dados dos seus projetos.</p></div></div><div class="service-grid">${cards}</div>${rec}</section>`}
function openService(key){const old=document.querySelector(".service-modal");if(old)old.remove();const info=SERVICE_MODULES[key],p=platforms[0]||null,modal=document.createElement("div");modal.className="service-modal";const context=p?`Negócio em foco: <b>${esc(p.name)}</b>`:"Nenhum negócio selecionado ainda.";modal.innerHTML=`<div class="service-box"><button class="close" type="button">×</button><span class="eyebrow-ui">V14 · SERVIÇO</span><h2>${info.icon} ${info.name}</h2><p>${info.desc}</p><div class="service-context">${context}</div><label>Nome do projeto<input id="svcName" value="${esc((p?.name||"Meu projeto")+" · "+info.name)}"></label><label>Objetivo / observações<textarea id="svcNotes" rows="5" placeholder="Descreva o que deseja preparar..."></textarea></label><div class="actions"><button class="secondary cancel">Cancelar</button><button class="primary save-service">💾 Salvar projeto</button></div></div>`;document.body.appendChild(modal);modal.querySelector(".close").onclick=()=>modal.remove();modal.querySelector(".cancel").onclick=()=>modal.remove();modal.querySelector(".save-service").onclick=()=>{saveServiceProject({id:crypto.randomUUID(),module:key,name:modal.querySelector("#svcName").value,notes:modal.querySelector("#svcNotes").value,businessId:p?.id||null,createdAt:new Date().toISOString()});modal.remove();setStatus("Projeto salvo na Central de Serviços.");renderServiceCentral()}}
/* ---------- Editor: criador + Designer + ADM (mesmo painel) ---------- */
const getP=(o,path)=>path.split(".").reduce((a,k)=>a==null?a:a[k],o);
function setP(o,path,v){const ks=path.split(".");const l=ks.pop();ks.reduce((a,k)=>a[k],o)[l]=v}
const inp=(path,label,type="text",ph="")=>`<label>${label}<input type="${type}" data-p="${path}" placeholder="${esc(ph)}" value="${esc(getP(ed,path)||"")}"></label>`;
const sel=(path,label,opts)=>`<label>${label}<select data-p="${path}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(getP(ed,path))===v?"selected":""}>${esc(t)}</option>`).join("")}</select></label>`;
const mini=(path,ph)=>`<input data-p="${path}" placeholder="${ph}" value="${esc(getP(ed,path)||"")}">`;
function openEditor(p,mode){ed=JSON.parse(JSON.stringify(p));edMode=mode;tab=mode==="adm"?"funcoes":"dados";$("edTitle").textContent=mode==="adm"?"ADM — "+p.name:mode==="create"?"Criar plataforma — "+p.name:"Editar — "+p.name;renderTab();$("editorDialog").showModal()}
function publicLinkFor(p){return shareLink(p,"site").url}
function admHeader(){const pub=publicLinkFor(ed);return `<div class="adm-top"><div><span class="eyebrow-ui">🔐 ADM V9</span><strong>${esc(ed.name)}</strong><small>Edite e publique o site do cliente.</small></div><div class="adm-links"><a class="primary" href="${esc(pub)}" target="_blank">🌐 Abrir site público</a><button type="button" data-act="copy-public">📋 Copiar link público</button></div></div>`}
function renderTab(){const T=TPL[tplKey(ed.type)];$("tabs").innerHTML=[["dados","① Informações"],["funcoes","② Funções"],["conteudo","③ Conteúdo"],["design","④ Visual"],["previa","⑤ Prévia"]].map(([k,v])=>`<button type="button" data-act="tab" data-v="${k}" class="${k===tab?"active":""}">${v}</button>`).join("");$("edBody").innerHTML=(edMode==="adm"?admHeader():"")+({dados:tabDados,funcoes:tabFuncoes,conteudo:tabConteudo,design:tabDesign,previa:tabPrevia})[tab]();if(tab==="previa")drawFrame()}
function tabDados(){return`<div class="creator-intro"><div><span class="eyebrow-ui">CRIADOR V9</span><h3>Monte o site de ${esc(ed.name||"seu negócio")}</h3><p>O Radar gera uma primeira versão visual e conteúdo sugerido. Confirme tudo antes de publicar.</p></div><button type="button" class="primary" data-act="auto">✨ Gerar automaticamente</button></div><h4>1. Nível do site</h4><div class="level-grid">${Object.entries(LEVELS).map(([k,v])=>`<label class="level-card ${ed.level===k?"selected":""}"><input type="radio" name="site-level" data-p="level" value="${k}" ${ed.level===k?"checked":""}><strong>${v.name}</strong><span>${v.desc}</span></label>`).join("")}</div><h4>2. Informações</h4><div class="admin-grid">${sel("type","Tipo",Object.entries(labels))}${inp("name","Nome")}${inp("title","Título principal")}${inp("phone","Telefone")}${inp("whatsapp","WhatsApp")}${inp("instagram","Instagram")}</div>${inp("address","Endereço")}<label>Descrição<textarea data-p="description" rows="3">${esc(ed.description||"")}</textarea></label>`}
function tabFuncoes(){ensureBusinessData(ed);let h='<div class="creator-intro"><div><span class="eyebrow-ui">V11 · MOTOR DO NEGÓCIO</span><h3>Funções de '+esc(labels[ed.type]||"estabelecimento")+'</h3><p>O Radar escolheu módulos de acordo com o tipo de negócio. Ative ou desative o que realmente existe no estabelecimento.</p></div><button type="button" class="primary" data-act="auto-functions">✨ Reaplicar funções do tipo</button></div><div class="feature-grid">';(ed.modules||[]).forEach(function(m,i){h+='<label class="feature-card '+(m.on?"selected":"")+'"><div><strong>'+esc(MODULE_LABELS[m.k]||m.k)+'</strong><span>'+esc(FEATURE_DESCS[m.k]||"Função configurável.")+'</span></div><input type="checkbox" data-module="'+i+'" '+(m.on?"checked":"")+'></label>'});h+='</div>';if(moduleOn(ed,"booking")||moduleOn(ed,"reservations")||moduleOn(ed,"orders"))h+='<div class="suggestion-note"><b>Automação V11:</b> os formulários públicos montam a mensagem e abrem o WhatsApp. Isso já funciona sem servidor; confirmação de horário/reserva continua dependendo do estabelecimento.</div>';const addRows=function(key,fields,label,addLabel){if(!moduleOn(ed,key))return"";let out='<h4>'+label+'</h4>';const maps={staff:[["name","Nome"],["role","Função"],["specialty","Especialidade"]],services:[["name","Serviço"],["price","Preço"],["duration","Duração"],["desc","Descrição"]],plans:[["name","Plano"],["price","Preço"],["desc","Descrição"]],classes:[["name","Modalidade"],["days","Dias"],["time","Horário"]],rooms:[["name","Acomodação"],["price","Diária"],["desc","Descrição"]],specialties:[["name","Especialidade"],["desc","Descrição"]]};(ed[fields]||[]).forEach(function(x,i){out+='<div class="row">';(maps[fields]||[]).forEach(function(f){out+=mini(fields+'.'+i+'.'+f[0],f[1])});out+='<button type="button" data-act="del" data-l="'+fields+'" data-i="'+i+'">🗑️</button></div>'});out+='<button type="button" data-act="add" data-l="'+fields+'">➕ '+addLabel+'</button>';return out};h+=addRows("staff","staff","Profissionais","Adicionar profissional");h+=addRows("services","services","Serviços","Adicionar serviço");h+=addRows("plans","plans","Planos","Adicionar plano");h+=addRows("classes","classes","Aulas / horários","Adicionar aula");h+=addRows("rooms","rooms","Acomodações","Adicionar acomodação");h+=addRows("specialties","specialties","Especialidades","Adicionar especialidade");return h;}
function tabConteudo(){const T=TPL[tplKey(ed.type)];return`<div class="suggestion-note">💡 <b>Sugestões automáticas:</b> estes itens foram inferidos pelo tipo de negócio. Não são dados confirmados do cliente. Revise nome, preço, descrição e imagem antes de publicar.</div><h4>${T.kind}</h4>${ed.items.map((it,i)=>`<div class="row">${mini(`items.${i}.cat`,"Categoria")}${mini(`items.${i}.name`,"Nome")}${mini(`items.${i}.price`,"Preço")}${mini(`items.${i}.desc`,"Descrição")}<input class="full" data-p="items.${i}.img" placeholder="URL da imagem (ou envie um arquivo abaixo)" value="${it.img&&it.img.startsWith("data:")?"(imagem enviada)":esc(it.img||"")}" ${it.img&&it.img.startsWith("data:")?"readonly":""}><input type="file" accept="image/*" data-file="items.${i}.img"><button type="button" data-act="del" data-l="items" data-i="${i}">🗑️ Remover</button></div>`).join("")}<div class="actions"><button type="button" data-act="add" data-l="items">➕ Adicionar item</button></div>`}
function galleryOptions(selected){const g=(ed.gallery||[]).filter(Boolean);return '<option value="">Automático</option>'+g.map((x,i)=>'<option value="'+esc(x)+'" '+(x===selected?'selected':'')+'>Imagem da galeria '+(i+1)+'</option>').join('')}
function tabDesign(){ensureDesignProposals(ed);const roles=imageRoles(ed.type);return `<div class="design-intro"><span class="eyebrow-ui">④ DESIGNER V14</span><h3>Designer original preservado + 3 propostas</h3><p>As funções antigas continuam. Escolha uma proposta e ajuste quatro controles que mudam a prévia de verdade.</p></div><div class="design-proposal-grid">${ed.designProposals.map((d,di)=>`<article class="design-proposal ${ed.selectedDesign===di?'selected':''}"><div class="proposal-head"><div><strong>${esc(d.name)}</strong><span>4 imagens · ${esc(roles.join(' · '))}</span></div><button type="button" class="${ed.selectedDesign===di?'primary':''}" data-act="select-design" data-di="${di}">${ed.selectedDesign===di?'✓ Selecionado':'Usar este design'}</button></div><div class="proposal-controls"><label>Tipografia<select data-design-control="font" data-di="${di}">${FONTS.map(f=>`<option value="${esc(f)}" ${d.font===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label><label>Formato das imagens<select data-design-control="shape" data-di="${di}">${[['round','Arredondado'],['square','Quadrado'],['pill','Pílula']].map(([v,t])=>`<option value="${v}" ${d.shape===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Estrutura<select data-design-control="hero" data-di="${di}">${Object.entries(LAYOUTS).map(([v,t])=>`<option value="${v}" ${d.hero===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Estilo<select data-design-control="style" data-di="${di}">${Object.entries(VISUAL_STYLES).map(([v,t])=>`<option value="${v}" ${d.visualStyle===v?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="design-images">${d.images.map((im,slot)=>`<label class="design-slot"><span>${slot+1}. ${esc(roles[slot])}</span><select data-design-image="${slot}" data-di="${di}">${galleryOptions(im)}</select>${im?`<img src="${esc(im)}" alt="">`:'<div class="image-placeholder">Sem imagem</div>'}</label>`).join('')}</div></article>`).join('')}</div><div class="design-gallery-note"><b>🖼️ Galeria:</b> cada quadro pode receber uma imagem da galeria. As propostas usam conjuntos/ordens diferentes quando existem imagens suficientes.</div><details><summary>⚙️ Controles originais avançados</summary><div class="style-grid">${Object.entries(VISUAL_STYLES).map(([id,v])=>`<button type="button" data-act="style" data-v="${id}" class="style-card ${ed.visualStyle===id?'selected':''}"><strong>${v.name}</strong><span>${v.desc}</span></button>`).join('')}</div><div class="admin-grid">${sel("layoutVariant","Hero / composição",Object.entries(LAYOUTS))}${sel("density","Ritmo",[["comfortable","Confortável"],["compact","Compacto"]])}${sel("btn","Botões",[["pill","Arredondados"],["round","Suaves"],["square","Quadrados"]])}${sel("font","Fonte",FONTS.map(f=>[f,f]))}${sel("dark","Tema",[["false","Claro"],["true","Escuro"]])}${inp("c1","Cor principal","color")}${inp("c2","Cor secundária","color")}</div></details><h4>Galeria do projeto</h4>${ed.gallery.map((g,i)=>`<div class="row two"><input data-p="gallery.${i}" placeholder="URL da imagem" value="${g.startsWith('data:')?'(imagem enviada)':esc(g)}" ${g.startsWith('data:')?'readonly':''}><button type="button" data-act="del" data-l="gallery" data-i="${i}">🗑️</button></div>`).join('')}<div class="actions"><button type="button" data-act="add" data-l="gallery">➕ Adicionar imagem</button><label class="secondary" style="margin:0">📷 Enviar imagem<input type="file" accept="image/*" data-file="gallery.new" hidden></label><button type="button" data-act="variant">🔄 Gerar outra versão</button><button type="button" data-act="images">🖼️ Reorganizar imagens</button></div>`}
function tabPrevia(){return`<div class="actions"><button type="button" data-act="dev" data-v="mobile">📱 Celular</button><button type="button" data-act="dev" data-v="desktop">🖥️ Computador</button></div><div class="frame-wrap"><iframe id="frame" style="width:${dev==="mobile"?"390px":"100%"}"></iframe></div>`}
function drawFrame(){const f=$("frame");if(f)f.srcdoc=fullDoc(ed)}
function readImg(file,max=900){return new Promise((ok,bad)=>{const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const s=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=im.width*s;c.height=im.height*s;c.getContext("2d").drawImage(im,0,0,c.width,c.height);ok(c.toDataURL("image/jpeg",.72))};im.onerror=bad;im.src=r.result};r.onerror=bad;r.readAsDataURL(file)})}
const NEW={items:()=>({cat:"",name:"",price:"",desc:"",img:""}),gallery:()=>"",reviews:()=>({name:"",stars:"5",text:""}),staff:()=>({name:"",role:"",specialty:"",img:""}),services:()=>({name:"",price:"",duration:"",desc:"",img:""}),plans:()=>({name:"",price:"",desc:""}),classes:()=>({name:"",days:"",time:"",desc:""}),rooms:()=>({name:"",price:"",desc:"",img:""}),specialties:()=>({name:"",desc:""})};
$("edBody").addEventListener("change",e=>{const el=e.target;if(el.dataset.module!=null){const i=+el.dataset.module;ed.modules[i].on=el.checked;renderTab();return}if(el.dataset.designControl!=null){changeDesignControl(ed,+el.dataset.di,el.dataset.designControl,el.value);renderTab();return}if(el.dataset.designImage!=null){updateDesignImage(ed,+el.dataset.di,+el.dataset.designImage,el.value);renderTab();return}});
$("edBody").addEventListener("input",e=>{const el=e.target,p=el.dataset.p;if(!p||el.readOnly)return;let v=el.type==="checkbox"?el.checked:el.value;if(p==="dark")v=v==="true";setP(ed,p,v);if(p==="level"){ed.sections=sectionsForLevel(v);renderTab()}});
$("edBody").addEventListener("change",async e=>{const el=e.target;if(el.dataset.p==="dark")setP(ed,"dark",el.value==="true");if(!el.dataset.file||!el.files[0])return;try{const url=await readImg(el.files[0],el.dataset.file==="banner"?1200:800);if(el.dataset.file==="gallery.new")ed.gallery.push(url);else setP(ed,el.dataset.file,url);renderTab()}catch{alert("Não foi possível ler a imagem.")}});
$("editorDialog").addEventListener("click",e=>{const b=e.target.closest("[data-act]");if(!b)return;const a=b.dataset.act,i=+b.dataset.i,l=b.dataset.l;
 if(a==="tab"){tab=b.dataset.v;renderTab()}else if(a==="dev"){dev=b.dataset.v;renderTab()}else if(a==="auto-functions"){ed.modules=defaultModules(ed.type);ensureBusinessData(ed);renderTab();setStatus("Funções recomendadas reaplicadas para este tipo de negócio.")}
 else if(a==="add"){ed[l].push(NEW[l]());renderTab()}else if(a==="del"){ed[l].splice(i,1);renderTab()}
 else if(a==="up"&&i>0||a==="down"&&i<ed.sections.length-1){const j=a==="up"?i-1:i+1;[ed.sections[i],ed.sections[j]]=[ed.sections[j],ed.sections[i]];renderTab()}
 else if(a==="preset"){const p=PRESETS.find(x=>x.id===b.dataset.v);Object.assign(ed,{c1:p.c1,c2:p.c2,font:p.font,dark:p.dark});renderTab()}
 else if(a==="select-design"){applyDesignProposal(ed,+b.dataset.di);renderTab();setStatus("Proposta de design aplicada à prévia.")}
 else if(a==="style"){ed.visualStyle=b.dataset.v;if(b.dataset.v==="premium")ed.dark=true;if(b.dataset.v==="minimal")ed.dark=false;renderTab()}
 else if(a==="variant"){rotateVariant(ed);rotateSiteImages(ed);repairImageRepetition(ed);renderTab()}
 else if(a==="images"){repairImageRepetition(ed);renderTab();setStatus("Imagens reorganizadas: o Radar evita repetir a mesma foto no site.")}
 else if(a==="copy-public"){copy(publicLinkFor(ed));b.textContent="✓ Link copiado";setTimeout(()=>b.textContent="📋 Copiar link público",1200)}
 else if(a==="ai-image"){ed.banner=aiImageURL(ed.type,"hero",ed.name);renderTab();setStatus("URL de imagem IA preparada. O provedor pode exigir autenticação conforme a API usada.")}
 else if(a==="auto"){if(ed.items.some(x=>x.name)&&!confirm("Substituir título, descrição, itens e visual pelo conteúdo automático do tipo?"))return;fillContent(ed);renderTab();setStatus("Conteúdo automático aplicado. Ajuste itens e preços de exemplo.")}});
function persistEd(){if(!ed.name.trim()){alert("Informe o nome.");return null}const i=platforms.findIndex(x=>x.id===ed.id);if(i<0)platforms.push(ed);else platforms[i]=ed;const p=ed;save();return p}
$("edSave").onclick=()=>{const p=persistEd();if(p){$("editorDialog").close();openEditor(p,"adm")}};
$("edPublish").onclick=()=>{const p=persistEd();if(p){$("editorDialog").close();publish(p.id)}};
$("edClose").onclick=()=>$("editorDialog").close();
/* ---------- Minhas plataformas / prévia / publicação ---------- */
function renderPlatforms(){$("platforms").innerHTML=platforms.length?platforms.map(p=>`<article class="platform"><div><h3>${esc(p.name)}</h3><span class="chip">${esc(labels[p.type])}</span> <span class="chip">${esc(LEVELS[p.level||"professional"].name)}</span> <span class="chip">${p.published?"Publicada":"Rascunho"}</span></div><p>${esc(p.description||"")}</p><div class="links plat-actions"><button data-adm="${p.id}" class="primary">⚙️ Abrir ADM</button><button data-edit="${p.id}">✏️ Editar dados</button><button data-preview="${p.id}">👁️ Prévia</button><button data-publish="${p.id}" class="primary">${p.published?"🔗 Copiar link":"🚀 Publicar"}</button>${p.published?`<button data-admlink="${p.id}">🔑 Link do ADM</button><button data-dl="${p.id}">⬇️ Baixar HTML</button>`:""}<button data-del="${p.id}">🗑️</button></div></article>`).join(""):'<div class="empty">Nenhuma plataforma criada. Use “Criar plataforma” em um resultado.</div>'}
function enc(p){return encodeURIComponent(btoa(unescape(encodeURIComponent(JSON.stringify(p)))))}
function dec(x){try{return JSON.parse(decodeURIComponent(escape(atob(decodeURIComponent(x)))))}catch{return null}}
function shareLink(p,param){let n=0;const q=JSON.parse(JSON.stringify(p)),cut=s=>(s&&s.startsWith("data:"))?(n++,""):s;q.banner=cut(q.banner);q.gallery=q.gallery.map(cut).filter(Boolean);q.items.forEach(i=>i.img=cut(i.img));return{url:location.origin+location.pathname+"?"+param+"="+enc(q),stripped:n}}
function copy(t){if(navigator.clipboard)navigator.clipboard.writeText(t).catch(()=>{})}
function publish(id){const p=platforms.find(x=>x.id===id);if(!p)return;if(!p.published){p.published=true;save()}const{url,stripped}=shareLink(p,"site");copy(url);
 alert("Plataforma publicada. Link copiado (quando o navegador permite):\n\n"+url+(stripped?`\n\nAtenção: ${stripped} imagem(ns) enviada(s) do computador não cabem no link. Use URLs de imagem ou “Baixar HTML” para levar tudo.`:"")+(url.length>8000?"\n\nO link ficou longo; se algum app cortar, use “Baixar HTML”.":""))}
function openPreview(id){const p=platforms.find(x=>x.id===id);if(!p)return;previewId=id;drawPreview();$("previewDialog").showModal()}
function drawPreview(){const p=platforms.find(x=>x.id===previewId);$("pvFrame").style.width=dev==="mobile"?"390px":"100%";$("pvFrame").srcdoc=fullDoc(p)}
document.querySelectorAll("[data-dev]").forEach(b=>b.onclick=()=>{dev=b.dataset.dev;drawPreview()});
$("closePreview").onclick=()=>$("previewDialog").close();$("publish").onclick=()=>{$("previewDialog").close();publish(previewId)};
/* ---------- Prospecção por localização V14 ---------- */
function saveProspectionLocation(){if(here)localStorage.setItem("radarProspectionLocationV14",JSON.stringify({...here,savedAt:new Date().toISOString()}))}
function regionCandidates(lat,lon){return [{name:"Região próxima",km:5},{name:"Região ampliada",km:10},{name:"Região de oportunidade",km:15},{name:"Região comercial",km:20}].map((r,i)=>({...r,lat:lat+[0.045,-0.06,0.075,-0.09][i],lon:lon+[0.05,0.07,-0.06,-0.1][i]}))}
async function scanOpportunityRegions(){if(!here)return;setStatus("Procurando regiões mais promissoras...");const out=[];for(const r of regionCandidates(here.lat,here.lon)){try{const d=await queryServers(overpassQuery({lat:r.lat,lon:r.lon},Math.min(5000,r.km*1000),"all"));const arr=(d.elements||[]).map((e,i)=>parseBusiness(e,i,{lat:r.lat,lon:r.lon})).filter(isValid),high=arr.filter(x=>analyze(x).score>=2).length;out.push({...r,count:arr.length,high,score:Math.min(99,45+Math.min(30,arr.length)+Math.min(24,high*2))})}catch{}}regionOpps=out.sort((a,b)=>b.score-a.score);render();setStatus("Localização salva. Regiões com maior potencial foram calculadas.")}
function renderRegions(){const mount=$("regionMount");if(!mount)return;if(!here){mount.innerHTML="";return}if(!regionOpps.length){mount.innerHTML=`<section class="panel region-panel"><div class="section-head"><h2>📍 Prospecção por região</h2><p>Sua localização está salva como referência. Encontre áreas mais distantes com maior potencial comercial.</p></div><button id="scanRegions" class="primary">🔥 Encontrar regiões com mais chances de negócio</button></section>`;return}mount.innerHTML=`<section class="panel region-panel"><div class="section-head"><h2>🔥 Regiões com maior potencial</h2><p>O Radar prioriza concentração de negócios e sinais de oportunidade, não apenas distância.</p></div><div class="region-grid">${regionOpps.slice(0,4).map(r=>`<article class="region-card"><span>~${r.km} km</span><h3>${esc(r.name)}</h3><strong>${r.score}/100</strong><p>${r.count} negócios válidos · ${r.high} com sinais de oportunidade</p><button class="secondary" data-region-lat="${r.lat}" data-region-lon="${r.lon}" data-region-name="${esc(r.name)}">Pesquisar nesta região</button></article>`).join("")}</div></section>`}
/* ---------- Localização e eventos globais ---------- */
function getPos(o){return new Promise((ok,bad)=>navigator.geolocation.getCurrentPosition(ok,bad,o))}
$("locate").onclick=async()=>{if(!navigator.geolocation){setStatus("Este navegador não suporta localização. Digite a cidade.",true);return}setStatus("Obtendo sua localização...");let pos;
 try{pos=await getPos({enableHighAccuracy:true,timeout:8000,maximumAge:60000})}catch(e){if(e.code===1){setStatus("Permissão de localização negada. Ative a localização para este site.",true);return}
  try{pos=await getPos({enableHighAccuracy:false,timeout:12000,maximumAge:300000})}catch{setStatus("Não foi possível obter sua localização (abra por https/localhost). Digite a cidade manualmente.",true);return}}
 const lat=pos.coords.latitude,lon=pos.coords.longitude;let label=`${lat.toFixed(5)}, ${lon.toFixed(5)}`;
 try{const d=await getJSON("https://nominatim.openstreetmap.org/reverse?"+new URLSearchParams({format:"jsonv2",lat,lon}),6000),a=d.address||{};const t=[a.suburb||a.neighbourhood,a.city||a.town||a.municipality||a.village,a.state].filter(Boolean).join(", ");if(t)label=t}catch{}
 here={lat,lon,label};saveProspectionLocation();$("location").value=label;setStatus("Localização encontrada e salva. Pesquisando negócios próximos...");await search();scanOpportunityRegions()};
$("search").onclick=search;$("location").addEventListener("keydown",e=>{if(e.key==="Enter")search()});
renderServiceCentral();
document.addEventListener("click",e=>{const g=s=>e.target.closest(s);let x;if(x=g("[data-service]")){openService(x.dataset.service);return}if(x=g("[data-marketing]")){openMarketing(x.dataset.marketing);return}if(x=g("#scanRegions")){scanOpportunityRegions();return}if(x=g("[data-region-lat]")){here={lat:+x.dataset.regionLat,lon:+x.dataset.regionLon,label:x.dataset.regionName};saveProspectionLocation();$("location").value=x.dataset.regionName;search();return}
 if(x=g(".create"))createPlatform(results.find(r=>r.id===x.dataset.id));
 if(x=g("[data-adm]"))openEditor(platforms.find(p=>p.id===x.dataset.adm),"adm");
 if(x=g("[data-edit]"))openEditor(platforms.find(p=>p.id===x.dataset.edit),"edit");
 if(x=g("[data-preview]"))openPreview(x.dataset.preview);
 if(x=g("[data-publish]"))publish(x.dataset.publish);
 if(x=g("[data-admlink]")){const p=platforms.find(p=>p.id===x.dataset.admlink),{url}=shareLink(p,"adm");copy(url);alert("Link do ADM copiado. Quem abrir este link edita esta plataforma no próprio navegador e publica um novo link:\n\n"+url)}
 if(x=g("[data-dl]")){const p=platforms.find(p=>p.id===x.dataset.dl),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([fullDoc(p)],{type:"text/html"}));a.download=(p.name||"site").replace(/[^\w-]+/g,"-")+".html";a.click()}
 if(x=g("[data-del]")){if(confirm("Excluir esta plataforma?")){platforms=platforms.filter(p=>p.id!==x.dataset.del);save()}}
 if(x=g("[data-copy]")){copy(x.dataset.copy);x.textContent="✓ Copiado";setTimeout(()=>x.textContent="Copiar telefone",900)}});
document.querySelectorAll("[data-filter]").forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll("[data-filter]").forEach(x=>x.classList.toggle("active",x===b));render()});
/* ---------- Abertura por link: ?site= (página pública) e ?adm= (painel do cliente) ---------- */
const qs=new URLSearchParams(location.search),siteQ=qs.get("site"),admQ=qs.get("adm");
if(siteQ){const p=dec(siteQ);if(p){const s=document.querySelector("link[rel=stylesheet]");if(s)s.remove();const pp=norm(p);document.title=pp.title||pp.name;document.head.insertAdjacentHTML("beforeend","<style>"+siteCSS(pp)+"</style>");document.body.innerHTML=siteHTML(pp)}}
else{platforms=platforms.map(x=>norm(x));localStorage.setItem(KEY,JSON.stringify(platforms));renderPlatforms();if(admQ){const p=dec(admQ);if(p){const pp=norm(p),i=platforms.findIndex(x=>x.id===pp.id);if(i<0)platforms.push(pp);save();openEditor(i<0?pp:platforms[i],"adm")}}}
